select a.codigo, a.nombre, a.stock_actual, count(u.id) unidades, count(u.id) filter (where u.estado='en_almacen') en_alm, count(u.id) filter (where u.estado='entregada') entreg, count(u.id) filter (where u.estado='instalada') inst, count(u.id) filter (where u.estado='devuelta') dev, count(u.id) filter (where u.estado='baja') baja, count(u.serie) con_serie
  from articulos a left join inventario_unidades u on u.articulo_id = a.id where a.tenant_id = 'e4b16a80-8500-418e-afaa-0e976b7d9b13' and a.codigo <> 'ART-0001' group by a.id, a.codigo, a.nombre, a.stock_actual order by a.codigo;
